package gen

import (
	"bytes"
	"fmt"
	"go/parser"
	"go/printer"
	"go/token"
	"io/fs"
	"path"
	"strconv"
	"strings"
	"text/template"

	"golang.org/x/tools/go/ast/astutil"
	"golang.org/x/tools/imports"
)

// Header starts every generated Go file (G4). It deliberately avoids the
// "DO NOT EDIT" form reserved for sqlc output: these files are owned code.
func Header(version string) string {
	return "// Code generated by semii " + version + ". You own this file; edit freely.\n\n"
}

// Renderer executes templates from an embedded tree.
type Renderer struct {
	FS      fs.FS
	Version string
}

var funcs = template.FuncMap{
	"quote":        strconv.Quote,
	"join":         strings.Join,
	"lower":        strings.ToLower,
	"camel":        Camel,
	"strategyCtor": func(s string) string { return strategyCtors[s] },
	// tag builds a struct tag from key/value pairs, skipping empty values:
	// {{tag "json" "id" "validate" ""}} -> `json:"id"`
	"tag": func(parts ...string) string {
		var tags []string
		for i := 0; i+1 < len(parts); i += 2 {
			if parts[i+1] != "" {
				tags = append(tags, parts[i]+":"+strconv.Quote(parts[i+1]))
			}
		}
		if len(tags) == 0 {
			return ""
		}
		return "`" + strings.Join(tags, " ") + "`"
	},
	"add":  func(a, b int) int { return a + b },
	"last": func(i, n int) bool { return i == n-1 },
}

// Render executes the template at name with data. Go files (target ending
// in .go) get the header and are formatted with goimports, which also
// drops imports the template listed but this resource does not use.
func (r Renderer) Render(name, target string, data any) ([]byte, error) {
	src, err := fs.ReadFile(r.FS, name)
	if err != nil {
		return nil, fmt.Errorf("template %s: %w", name, err)
	}
	t, err := template.New(path.Base(name)).Funcs(funcs).Option("missingkey=error").Parse(string(src))
	if err != nil {
		return nil, fmt.Errorf("template %s: %w", name, err)
	}
	var buf bytes.Buffer
	if err := t.Execute(&buf, data); err != nil {
		return nil, fmt.Errorf("template %s: %w", name, err)
	}
	if !strings.HasSuffix(target, ".go") {
		return buf.Bytes(), nil
	}
	return FormatGo(target, append([]byte(Header(r.Version)), buf.Bytes()...))
}

// FormatGo runs goimports on src (G1). Imports are never searched for:
// templates list every import they may need.
func FormatGo(filename string, src []byte) ([]byte, error) {
	out, err := imports.Process(filename, src, &imports.Options{
		Comments: true, TabIndent: true, TabWidth: 8, FormatOnly: false,
	})
	if err != nil {
		return nil, fmt.Errorf("format %s: %w\n%s", filename, err, numbered(src))
	}
	return out, nil
}

func numbered(src []byte) string {
	lines := strings.Split(string(src), "\n")
	for i, l := range lines {
		lines[i] = fmt.Sprintf("%4d  %s", i+1, l)
	}
	return strings.Join(lines, "\n")
}

// AddImports adds import paths ("path" or "name path") to a Go source file
// and reformats it.
func AddImports(filename string, src []byte, paths ...string) ([]byte, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filename, src, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("parse %s: %w", filename, err)
	}
	for _, p := range paths {
		// "name path" adds a named import.
		if name, path, ok := strings.Cut(p, " "); ok {
			astutil.AddNamedImport(fset, f, name, path)
		} else {
			astutil.AddImport(fset, f, p)
		}
	}
	var buf bytes.Buffer
	cfg := printer.Config{Mode: printer.UseSpaces | printer.TabIndent, Tabwidth: 8}
	if err := cfg.Fprint(&buf, fset, f); err != nil {
		return nil, err
	}
	return FormatGo(filename, buf.Bytes())
}
